<?php
require __DIR__.'/../includes/bootstrap.php';if(!$user)redirect('../login.php');
$date=$_GET['date']??date('Y-m-d');$d=is_string($date)?DateTime::createFromFormat('!Y-m-d',$date):false;if(!$d||$d->format('Y-m-d')!==$date){http_response_code(400);exit('Invalid date.');}
$rows=array_filter(requests(),fn($r)=>substr($r['start_datetime'],0,10)<=$date&&substr($r['end_datetime'],0,10)>=$date&&in_array($r['status'],['Approved','Dispatched','Returned','Completed']));usort($rows,fn($a,$b)=>strcmp($a['start_datetime'],$b['start_datetime']));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Daily vehicle schedule · <?=e($date)?></title><link rel="stylesheet" href="../assets/css/print.css?v=<?=filemtime(__DIR__.'/../assets/css/print.css')?>"></head><body class="landscape"><div class="no-print"><button onclick="window.print()">Print / Save as PDF</button><a href="../index.php?page=calendar">Back to calendar</a></div><main class="requisition-slip"><header><h2><?=e(setting('organization'))?></h2><h1>DAILY VEHICLE USE SCHEDULE</h1><p><?=shortdate($date,'l, F j, Y')?></p></header><table class="daily"><thead><tr><th>Time</th><th>Vehicle / plate</th><th>Office</th><th>Requester</th><th>Destination</th><th>Driver</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=shortdate($r['start_datetime'],'g:i A')?> – <?=shortdate($r['end_datetime'],'g:i A')?></td><td><?=e($r['model'])?><br><?=e($r['plate'])?></td><td><?=e($r['office_name'])?></td><td><?=e($r['requester_name'])?></td><td><?=e($r['destination'])?></td><td><?=e($r['driver_name'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7">No confirmed trips for this date.</td></tr><?php endif?></tbody></table><footer>Prepared by <?=e($user['full_name'])?> · <?=date('M j, Y g:i A')?> · Records visible to <?=e($user['role'])?></footer></main></body></html>
